package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the system time.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock is the production Clock.
var RealClock Clock = realClock{}

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket starts full with capacity tokens and refills at rate
// tokens per second. All methods are safe for concurrent use.
type Limiter struct {
	mu      sync.Mutex
	tokens  float64
	capacity float64
	rate    float64 // tokens per second
	last    time.Time
	clock   Clock
}

// ErrInvalidConfig is returned by New for non-positive capacity or rate.
var ErrInvalidConfig = errors.New("ratelimit: capacity and rate must be > 0")

// New returns a full Limiter with the given burst capacity and refill
// rate (tokens per second). If clock is nil, the real clock is used.
func New(capacity, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 || rate <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = RealClock
	}
	now := clock.Now()
	return &Limiter{
		tokens:   capacity,
		capacity: capacity,
		rate:     rate,
		last:     now,
		clock:    clock,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, consuming them if so.
// Tokens accrue continuously at the configured rate, capped at capacity.
func (l *Limiter) AllowN(n float64) bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.last = now
	}
	if n < 0 || n > l.tokens {
		return false
	}
	l.tokens -= n
	return true
}

// Tokens returns the current number of available tokens.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.tokens
}
