package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the system time.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket starts full and refills at rate tokens per second,
// up to capacity.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	capacity float64
	rate     float64 // tokens per second
	last     time.Time
	clock    Clock
}

var ErrInvalidConfig = errors.New("ratelimit: capacity and rate must be > 0")

// New creates a Limiter with the given burst capacity and refill rate
// (tokens per second). The bucket starts full.
func New(capacity, rate float64) (*Limiter, error) {
	return NewWithClock(capacity, rate, realClock{})
}

// NewWithClock is New with an injectable Clock.
func NewWithClock(capacity, rate float64, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if capacity <= 0 || rate <= 0 {
		return nil, ErrInvalidConfig
	}
	return &Limiter{
		tokens:   capacity,
		capacity: capacity,
		rate:     rate,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, refilling the bucket
// based on elapsed time first. If allowed, n tokens are consumed.
func (l *Limiter) AllowN(n float64) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.last = now
	}
	if n > l.tokens {
		return false
	}
	l.tokens -= n
	return true
}

// Tokens returns the current number of available tokens (after refill).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	elapsed := l.clock.Now().Sub(l.last).Seconds()
	t := l.tokens + elapsed*l.rate
	if t > l.capacity {
		t = l.capacity
	}
	return t
}
