// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// SystemClock uses the real wall clock.
type SystemClock struct{}

// Now returns the current time.
func (SystemClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket holds up to Burst tokens and refills at Rate tokens per second.
type Limiter struct {
	mu sync.Mutex

	burst    float64
	rate     float64 // tokens per second
	tokens   float64
	lastTime time.Time
	clock    Clock
}

// ErrInvalidConfig is returned by New for non-positive burst or rate.
var ErrInvalidConfig = errors.New("ratelimit: burst and rate must be > 0")

// New creates a Limiter with a full bucket of burst tokens refilling
// at rate tokens per second. clock may be nil, defaulting to SystemClock.
func New(burst int, rate float64, clock Clock) (*Limiter, error) {
	if burst <= 0 {
		return nil, ErrInvalidConfig
	}
	if rate <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = SystemClock{}
	}
	now := clock.Now()
	return &Limiter{
		burst:    float64(burst),
		rate:     rate,
		tokens:   float64(burst),
		lastTime: now,
		clock:    clock,
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now.
// If allowed, the tokens are deducted.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.lastTime).Seconds()
	if elapsed > 0 {
		l.tokens = minF(l.burst, l.tokens+elapsed*l.rate)
		l.lastTime = now
	}

	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

func minF(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
