		burst int
		steps []struct {
			advance time.Duration
			n       int
			want    bool
		}
	}{
		{
			name:  "burst exhausted then refills",
			rate:  1, // 1 token per second
			burst: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},  // consume full burst
				{0, 1, false}, // empty
				{time.Second, 1, true},
				{time.Second, 1, true},
				{0, 1, false},
			},
		},
		{
			name:  "tokens capped at burst",
			rate:  1,
			burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{10 * time.Second, 1, true}, // only 1 token accrued despite 10s
				{0, 1, false},
			},
		},
		{
			name:  "fractional refill",
			rate:  2,
			burst: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
