func TestConcurrentAccess(t *testing.T) {
	fc := &fakeClock{t: time.Unix(0, 0)}
	l, err := New(1000, 100, fc)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	var wg sync.WaitGroup
	allowed := make([]bool, 200)
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			allowed[i] = l.AllowN(fc.Now(), 1)
		}(i)
	}
	wg.Wait()
	count := 0
	for _, a := range allowed {
		if a {
			count++
		}
	}
	if count != 100 {
		t.Errorf("allowed %d requests, want exactly 100 (burst)", count)
	}
